BEGIN TRANSACTION;
CREATE TABLE "AttendanceEvent" ("attendance_id" TEXT, "assignment_id" TEXT, "emp_id" TEXT, "attendance_status" TEXT, "check_in" TEXT, "check_out" TEXT, PRIMARY KEY ("attendance_id"), FOREIGN KEY ("assignment_id") REFERENCES "ShiftAssignment"("assignment_id"), FOREIGN KEY ("emp_id") REFERENCES "Employee"("emp_id"));
CREATE TABLE "CoverageGap" ("gap_id" TEXT, "requirement_id" TEXT, "assigned_staff" TEXT, "gap" TEXT, "status" TEXT, PRIMARY KEY ("gap_id"), FOREIGN KEY ("requirement_id") REFERENCES "CoverageRequirement"("requirement_id"));
CREATE TABLE "CoverageRequirement" ("requirement_id" TEXT, "date" TEXT, "template_id" TEXT, "skill_id" TEXT, "min_staff_required" TEXT, PRIMARY KEY ("requirement_id"), FOREIGN KEY ("template_id") REFERENCES "ShiftTemplate"("template_id"), FOREIGN KEY ("skill_id") REFERENCES "Skill"("skill_id"));
CREATE TABLE "Employee" ("emp_id" TEXT, "name" TEXT, "team_id" TEXT, "primary_skill_id" TEXT, "weekly_hours_cap" TEXT, PRIMARY KEY ("emp_id"), FOREIGN KEY ("team_id") REFERENCES "Team"("team_id"), FOREIGN KEY ("primary_skill_id") REFERENCES "Skill"("skill_id"));
CREATE TABLE "EmployeeSkill" ("emp_id" TEXT, "skill_id" TEXT, "proficiency" TEXT, PRIMARY KEY ("emp_id", "skill_id"), FOREIGN KEY ("emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("skill_id") REFERENCES "Skill"("skill_id"));
CREATE TABLE "HolidayCalendar" ("holiday_date" TEXT, "holiday_name" TEXT, PRIMARY KEY ("holiday_date"));
CREATE TABLE "LeaveRequest" ("leave_id" TEXT, "emp_id" TEXT, "start_date" TEXT, "end_date" TEXT, "status" TEXT, PRIMARY KEY ("leave_id"), FOREIGN KEY ("emp_id") REFERENCES "Employee"("emp_id"));
CREATE TABLE "LeaveRequestEvent" ("leave_event_id" TEXT, "leave_id" TEXT, "event_type" TEXT, "from_status" TEXT, "to_status" TEXT, "event_at" TEXT, "actor" TEXT, PRIMARY KEY ("leave_event_id"), FOREIGN KEY ("leave_id") REFERENCES "LeaveRequest"("leave_id"));
CREATE TABLE "OvertimeSummary" ("summary_id" TEXT, "emp_id" TEXT, "week_start" TEXT, "scheduled_hours" TEXT, "actual_worked_seconds" TEXT, "weekly_hours_cap" TEXT, "scheduled_overtime_hours" TEXT, "actual_overtime_seconds" TEXT, PRIMARY KEY ("summary_id"), FOREIGN KEY ("emp_id") REFERENCES "Employee"("emp_id"));
CREATE TABLE "ShiftAssignment" ("assignment_id" TEXT, "emp_id" TEXT, "date" TEXT, "template_id" TEXT, PRIMARY KEY ("assignment_id"), FOREIGN KEY ("emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("template_id") REFERENCES "ShiftTemplate"("template_id"));
CREATE TABLE "ShiftAssignmentEvent" ("assignment_event_id" TEXT, "assignment_id" TEXT, "previous_emp_id" TEXT, "new_emp_id" TEXT, "event_type" TEXT, "event_at" TEXT, "actor" TEXT, "related_swap_id" TEXT, PRIMARY KEY ("assignment_event_id"), FOREIGN KEY ("assignment_id") REFERENCES "ShiftAssignment"("assignment_id"), FOREIGN KEY ("previous_emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("new_emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("related_swap_id") REFERENCES "SwapRequest"("swap_id"));
CREATE TABLE "ShiftTemplate" ("template_id" TEXT, "shift_name" TEXT, "start_time" TEXT, "end_time" TEXT, "hours" TEXT, PRIMARY KEY ("template_id"));
CREATE TABLE "Skill" ("skill_id" TEXT, "skill_name" TEXT, PRIMARY KEY ("skill_id"));
CREATE TABLE "SwapRequest" ("swap_id" TEXT, "requesting_emp_id" TEXT, "target_emp_id" TEXT, "assignment_id" TEXT, "status" TEXT, PRIMARY KEY ("swap_id"), FOREIGN KEY ("requesting_emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("target_emp_id") REFERENCES "Employee"("emp_id"), FOREIGN KEY ("assignment_id") REFERENCES "ShiftAssignment"("assignment_id"));
CREATE TABLE "SwapRequestEvent" ("swap_event_id" TEXT, "swap_id" TEXT, "event_type" TEXT, "from_status" TEXT, "to_status" TEXT, "event_at" TEXT, "actor" TEXT, PRIMARY KEY ("swap_event_id"), FOREIGN KEY ("swap_id") REFERENCES "SwapRequest"("swap_id"));
CREATE TABLE "Team" ("team_id" TEXT, "team_name" TEXT, PRIMARY KEY ("team_id"));
COMMIT;
